const input=$json.body ?? $json;
const deal=input.deal ?? input;
const buyer=input.buyer ?? {};
const seller=input.seller ?? {};
const property=input.property ?? {};
const agreement=input.agreement ?? {};
const funding=input.funding ?? {};
const documents=input.documents ?? {};
const dates=input.critical_dates ?? {};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const requiredDocs=Array.isArray(documents.required)?documents.required:[];
const suppliedDocs=Array.isArray(documents.supplied)?documents.supplied:[];
const missingDocs=requiredDocs.filter(d=>!suppliedDocs.includes(d));
const agreementType=String(agreement.type||deal.agreement_type||'').toLowerCase();
const validAgreement=['assignment','novation','double_close'].includes(agreementType);
const executed=agreement.execution_state==='executed'||deal.execution_state==='executed';
const buyerCommitted=buyer.commitment_status==='committed'||input.commitment_status==='committed';
const fundingReady=funding.ready===true||funding.status==='verified'||(agreementType!=='double_close'&&funding.required!==true);
const criticalDatePresent=Boolean(dates.closing_date||dates.assignment_deadline||dates.termination_date);
const openBlockers=blockers.filter(b=>b&&b.resolved!==true&&b.status!=='resolved');
const identityReady=Boolean((buyer.id||buyer.buyer_id)&&(deal.id||deal.deal_id)&&(property.id||property.property_id));
const ready=Boolean(validAgreement&&executed&&buyerCommitted&&fundingReady&&identityReady&&missingDocs.length===0&&openBlockers.length===0&&criticalDatePresent);
let route='human_review';
if(ready) route='transaction_readiness';
else if(!executed) route='contract_execution';
else if(!buyerCommitted) route='buyer_commitment';
else if(!fundingReady) route='funding_readiness';
else if(missingDocs.length||openBlockers.length||!criticalDatePresent) route='readiness_blocked';
return [{json:{workflow_id:'WF-134',workflow_name:'Disposition Commitment → Transaction Readiness Controller',status:ready?'ready':'blocked',route,transaction_ready:ready,deal_id:deal.id??deal.deal_id??null,lead_id:deal.lead_id??seller.lead_id??null,property_id:property.id??property.property_id??null,buyer_id:buyer.id??buyer.buyer_id??null,agreement_type:agreementType||null,agreement_execution_state:agreement.execution_state??deal.execution_state??null,buyer_commitment_status:buyer.commitment_status??input.commitment_status??null,funding_status:funding.status??null,funding_ready:fundingReady,missing_documents:missingDocs,open_blockers:openBlockers,critical_dates:dates,identity_ready:identityReady,next_workflow:ready?'WF-125/126 transaction readiness & closing coordination':route==='contract_execution'?'WF-124 contract execution & signature outcome controller':route==='buyer_commitment'?'WF-132 buyer outreach & commitment sequence':route==='funding_readiness'?'WF-127 buyer/assignee & funding readiness controller':'human_review',crm_activity:{event_type:'disposition_commitment_transaction_readiness',outcome:ready?'ready':'blocked',route,deal_id:deal.id??deal.deal_id??null},idempotency_key:'wf-134:disposition-commitment-readiness:'+(deal.id??deal.deal_id??input.event_id??'unknown')}}}];
